INSERT INTO public.regulation_articles (id, chapter_id, code, title, content, content_type, sort_order) VALUES
('chuong-vi-ieu-31', 'qclv-chuong-vi', 'Điều 31', 'Khen thưởng, kỷ luật, giải quyết khiếu nại, tố cáo liên quan cán bộ, viên chức, người lao động; công tác phòng chống tham nhũng', '1. Khen thưởng, kỷ luật

a) Chế độ khen thưởng thường xuyên, đột xuất hàng năm thực hiện theo Quy chế thi đua, khen thưởng của Ban QLDA và theo quy định của pháp luật;', 'text', 7),
('chuong-vii-ieu-32', 'qclv-chuong-vii', 'Điều 32', 'Hiệu lực thi hành', '1. Quy chế làm việc có hiệu lực từ ngày ban hành. Quy chế này được phổ biến, quán triệt đến toàn thể cán bộ, viên chức và người lao động thuộc Ban QLDA tỉnh để thực hiện.

2. Giám đốc, Phó Giám đốc, các phòng trực thuộc, các viên chức, người lao động Ban QLDA có trách nhiệm thực hiện Quy chế này. Giám đốc Ban QLDA có trách nhiệm phân công nhiệm vụ cụ thể cho các Phó Giám đốc, các phòng trực thuộc và viên chức, người lao động phù hợp với thực tiễn hoạt động của Ban QLDA đảm bảo đúng quy định của pháp luật và các quy định tại Quy chế này.

3. Trong quá trình tổ chức thực hiện, trường hợp các quy định tại Quy chế này có thay đổi do văn bản pháp luật mới ban hành hoặc có nội dung khác với quy định của cấp có thẩm quyền, thì thực hiện theo quy định của pháp luật hiện hành; hoặc nếu có vấn đề vướng mắc trưởng/phụ trách các phòng kịp thời báo cáo Lãnh đạo Ban QLDA (qua phòng Hành chính \- Tổng hợp) để nghiên cứu sửa đổi, bổ sung cho phù hợp./.

|  | BAN QLDA ĐẦU TƯ XÂY DỰNG  CÔNG TRÌNH DÂN DỤNG  VÀ HẠ TẦNG KHU VỰC |

| :---- | :---: |', 'text', 1),
('chuong-chung-dieu-1', 'qcdgxl-chung', 'chuong-chung-dieu-1', 'Điều 1. Ban hành kèm theo Quyết định này Quy chế Đánh giá, xếp loại hàng tháng đối với cán bộ, viên chức, người lao động thuộc Ban Quản lý dự án đầu tư xây dựng công trình Dân dụng và Hạ tầng khu vực tỉnh Hà Tĩnh.', 'content: ( )', 'text', 1),
('chuong-chung-dieu-2', 'qcdgxl-chung', 'chuong-chung-dieu-2', 'Điều 2. Quyết định này có hiệu lực kể từ ngày ban hành.', 'content: ( )', 'text', 2),
('chuong-chung-dieu-3', 'qcdgxl-chung', 'chuong-chung-dieu-3', 'Điều 3. Trưởng các phòng: Hành chính \- Tổng hợp, Quản lý dự án 1, Quản lý dự án 2, Quản lý dự án 3, Kế hoạch \- Đấu thầu, Kỹ thuật \- Thẩm định, Phát triển dịch vụ và các tổ chức, cá nhân có liên quan chịu trách nhiệm thi hành Quyết định này./.', '| *Nơi nhận:*		         	     	 - Như điều 2; - Giám đốc, các Phó Giám đốc; - Lưu VT, HC-TH./.  | GIÁM ĐỐC Nguyễn Quang Linh  |

| :---- | ----- |

| UBND TỈNH HÀ TĨNH BAN QLDA ĐẦU TƯ XÂY DỰNG CÔNG TRÌNH DÂN DỤNG VÀ HẠ TẦNG KHU VỰC  | CỘNG HOÀ XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc  |

| ----- | :---: |

#

# **QUY CHẾ**

**Đánh giá, xếp loại hàng tháng đối với cán bộ, viên chức, người lao động thuộc Ban Quản lý dự án đầu tư xây dựng công trình**

**Dân dụng** **và Hạ tầng khu vực tỉnh Hà Tĩnh**

#', 'text', 3),
('chuong-i-dieu-1', 'qcdgxl-chuong-i', 'chuong-i-dieu-1', 'Điều 1. Phạm vi điều chỉnh và đối tượng áp dụng', '1. Phạm vi điều chỉnh: Quy chế này quy định việc đánh giá, xếp loại hàng tháng lấy cơ sở đánh giá, xếp loại hàng năm và chi thu nhập tăng thêm đối với các phòng; cán bộ, viên chức, người lao động thuộc Ban Quản lý dự án đầu tư xây dựng công trình Dân dụng và Hạ tầng khu vực tỉnh Hà Tĩnh (Ban QLDA).

2. Đối tượng áp dụng: Viên chức, người lao động và các phòng chuyên môn thuộc Ban QLDA.', 'text', 1),
('chuong-i-dieu-2', 'qcdgxl-chuong-i', 'chuong-i-dieu-2', 'Điều 2. Mục đích', '1. Tiêu chí đánh giá, xếp loại hàng tháng của viên chức, người lao động Ban QLDA là căn cứ để bình xét khen thưởng, chi trả thu nhập tăng thêm hàng năm; là căn cứ để đánh giá, xếp loại thi đua; đồng thời là cơ sở để bố trí, sử dụng, quy hoạch, đề bạt, đào tạo, bồi dưỡng và thực hiện chính sách đối với cán bộ, viên chức, người lao động theo quy định và theo yêu cầu nhiệm vụ của cơ quan.

2. Đánh giá xếp loại hàng tháng đối với cán bộ, viên chức, người lao động nhằm phát huy vai trò, trách nhiệm của người đứng đầu trong công tác lãnh đạo, quản lý, siết chặt kỷ luật, kỷ cương, chuẩn hóa, xây dựng phong cách làm việc chuyên nghiệp; nâng cao ý thức trách nhiệm, tính tự giác trong thực thi công vụ của cán bộ, viên chức, người lao động; tạo môi trường sáng tạo, đổi mới, phát triển, nâng cao chất lượng, hiệu quả hoạt động của cơ quan.', 'text', 2),
('chuong-i-dieu-3', 'qcdgxl-chuong-i', 'chuong-i-dieu-3', 'Điều 3. Yêu cầu', '1. Căn cứ vào Kế hoạch khung hàng năm của Ban QLDA, nhiệm vụ chuyên môn của các phòng và khối lượng công việc tồn đọng, các phòng thuộc Ban QLDA phải xây dựng kế hoạch công tác tháng, quý, năm; phân công cụ thể (cán bộ trực tiếp phụ trách, lãnh đạo phòng trực tiếp quản lý, lãnh đạo Ban phụ trách); nội dung công việc được giao; tiến độ, thời gian thực hiện, hoàn thành; xác định kết quả đầu ra của mỗi nhiệm vụ được giao. Trên cơ sở kế hoạch công tác của phòng, cá nhân xây dựng kế hoạch thực hiện tháng, quý, năm.

2. Việc đánh giá, xếp loại hàng tháng đối với cán bộ, viên chức, lao động phải thực hiện theo nguyên tắc tập trung dân chủ, chính xác, khách quan, công bằng, đúng thực chất và đúng trình tự quy định. Phải thực hiện đánh giá đa chiều, liên tục, lượng hóa được kết quả thực hiện nhiệm vụ của từng cán bộ, viên chức, người lao động gắn với kết quả công tác của từng bộ phận, từng phòng chuyên môn (trên cơ sở phân tích về tổng khối lượng và tính chất, mức độ của công việc).', 'text', 3),
('chuong-i-dieu-4', 'qcdgxl-chuong-i', 'chuong-i-dieu-4', 'Điều 4. Nguyên tắc đánh giá, xếp loại chất lượng', '1. Trưởng các phòng trực tiếp lãnh đạo, giao nhiệm vụ, đồng thời là người thực hiện nhận xét, đánh giá, xếp loại viên chức và người lao động thuộc đơn vị mình. Giám đốc Ban QLDA là người đứng đầu cơ quan quyết định việc xếp loại, đánh giá cán bộ, viên chức, người lao động theo phân cấp quản lý và chịu trách nhiệm về quyết định của mình.

2. Việc đánh giá, xếp loại phải căn cứ vào chức trách, nhiệm vụ được giao và kết quả thực hiện nhiệm vụ. Việc đánh giá cần làm rõ ưu điểm, khuyết điểm, tồn tại, hạn chế về phẩm chất, năng lực, trình độ của cán bộ, viên chức, người lao động.

3. Bảo đảm dân chủ, khách quan, chính xác, công khai, minh bạch, xuyên suốt, liên tục, đa chiều.

4. Việc đánh giá, xếp loại viên chức lãnh đạo, quản lý phải dựa vào kết quả hoạt động của cơ quan, đơn vị được giao quản lý, phục trách. Mức độ hoàn thành nhiệm vụ của người đứng đầu không được cao hơn mức độ hoàn thành nhiệm vụ của đơn vị được giao quản lý, phụ trách.

5. Trường hợp cán bộ, viên chức, lao động không hoàn thành nhiệm vụ do yếu tố khách quan, bất khả kháng thì được xem xét trong quá trình đánh giá, xếp loại.', 'text', 4),
('chuong-i-dieu-5', 'qcdgxl-chuong-i', 'chuong-i-dieu-5', 'Điều 5. Thời hạn định kỳ đánh giá, xếp loại', '1. Đối với Ban QLDA tỉnh và các phòng chuyên môn: Thực hiện hằng quý/năm.

2. Đối với viên chức, người lao động: Thực hiện hàng tháng làm cơ sở để đánh giá, xếp loại chất lượng hàng năm.

Đối với Giám đốc, Phó giám đốc Ban QLDA được đánh giá xếp loại hàng quý. Căn cứ vào kết quả đánh giá, xếp loại hàng quý các phòng được giao phụ trách của các Phó Giám đốc và kết quả đánh giá, xếp loại hàng quý của Ban QLDA tỉnh để đề xuất UBND tỉnh đánh giá xếp loại Giám đốc, Phó giám đốc.', 'text', 5)
